const problems = [{"value": "additif 10D", "label": "additif 10D"}, {"value": "additif 20D", "label": "additif 20D"}, {"value": "additif 2D", "label": "additif 2D"}, {"value": "additif 5D", "label": "additif 5D"}, {"value": "call", "label": "call"}, {"value": "carré", "label": "carré"}, {"value": "exponentielle", "label": "exponentielle"}, {"value": "interactions 10D", "label": "interactions 10D"}, {"value": "interactions 20D", "label": "interactions 20D"}, {"value": "interactions 2D", "label": "interactions 2D"}, {"value": "interactions 5D", "label": "interactions 5D"}, {"value": "linéaire", "label": "linéaire"}, {"value": "pics multiples", "label": "pics multiples"}, {"value": "projection 10D", "label": "projection 10D"}, {"value": "projection 20D", "label": "projection 20D"}, {"value": "projection 2D", "label": "projection 2D"}, {"value": "projection 5D", "label": "projection 5D"}, {"value": "sinus", "label": "sinus"}, {"value": "événement rare", "label": "événement rare"}];

const regimes = [
  {value:"exact:128",label:"128 appels exacts"},
  {value:"exact:512",label:"512 appels exacts"},
  {value:"exact:2048",label:"2 048 appels exacts"},
  {value:"exact:8192",label:"8 192 appels exacts"},
  {value:"cpu:512",label:"CPU visé · ancre 512"},
  {value:"cpu:2048",label:"CPU visé · ancre 2 048"},
];
const number = new Intl.NumberFormat("fr-FR", {maximumSignificantDigits:4});
const integer = new Intl.NumberFormat("fr-FR");
function metric(v: number) {
  if (Math.abs(v) < 1e-14) return "0";
  if (Math.abs(v) < .0001) return v.toExponential(3).replace(".",",");
  return number.format(v);
}
export default function GaussianStratificationBenchmark() {
  const theme = useHostTheme();
  const [problem, chooseProblem] = useState("projection 20D");
  const [regime, chooseRegime] = useState("exact:8192");
  const [sort, chooseSort] = useState("rmse");
  const column = sort === "cpu" ? 5 : 2;
  const reference = problem.includes("D") ? "Projection" : "Direct";
  const entries = [...data[problem+":"+regime]].sort((a,b) => a[column]-b[column]);
  const baseline = entries.find((r) => r[0] === reference)?.[5] ?? 1;
  const timed = regime.startsWith("cpu");
  const rows = entries.map(([method,calls,rmse,variance,bias,cpu]) => {
    const ratio = cpu/baseline;
    const matched = ratio >= .8 && ratio <= 1.25;
    const base = [method,integer.format(calls),metric(rmse),metric(variance),metric(bias),metric(cpu)];
    return timed ? [...base, matched ? "Oui" : "Non"] : base;
  });
  const headers = ["Méthode","Appels exacts","RMSE","Variance","Biais","CPU médian (ms)"];
  return (
    <Stack gap={20} style={{maxWidth:1120,margin:"0 auto",padding:24}}>
      <Stack gap={8}>
        <H1>Décomposition gaussienne stratifiée</H1>
        <p style={{color:theme.accent.primary,fontSize:16,margin:0}}>
          La grille réduit parfois la variance du MC. La projection directe garde l’avantage sur les cas projetés.
        </p>
        <Text>
          Sur l’exponentielle en dimension 20 à temps apparié, la grille emploie
          1 562 appels contre 2 072 pour la projection directe. Son erreur est 2,35 fois plus élevée.
        </Text>
      </Stack>
      <Stack gap={8}>
        <H2>Comparer les plans de tirage</H2>
        <Row gap={12} style={{flexWrap:"wrap"}}>
          <label>Intégrande <Select value={problem} onChange={chooseProblem} options={problems} /></label>
          <label>Régime <Select value={regime} onChange={chooseRegime} options={regimes} /></label>
          <label>Tri <Select value={sort} onChange={chooseSort} options={[
            {value:"rmse",label:"RMSE"},{value:"cpu",label:"Temps CPU"},
          ]} /></label>
        </Row>
        <Table striped headers={timed ? [...headers,"Temps apparié"] : headers} rows={rows}
          columnAlign={["left","right","right","right","right","right","left"]} />
        <small style={{color:theme.text.secondary}}>
          100 réplications · RMSE et biais en unités de l’espérance · variance en unités au carré.
          {timed ? " Temps apparié si le ratio à la référence directe ou projetée est entre 0,8 et 1,25." : ""}
        </small>
      </Stack>
    </Stack>
  );
}
